svg.script:
(function () {
  var svgns = 'http://www.w3.org/2000/svg';
  var dotsG = document.getElementById('dots'), paddle = document.getElementById('paddle'), statusT = document.getElementById('status');
  var dots = [], kept = 0, lost = 0, px = 195, keys = {};
  var best = 0, dailyFired = false;
  var labels = ['D1', 'D7', 'D30'];

  // —— retention + contact (shared pattern) ——
  var GAME = 'cohort', DAILY_TARGET = 25;
  var DAILY_GAMES = ['snake', '2048', 'pong', 'abtest', 'funnel', 'cohort', 'sql', 'metric', 'retention', 'bottleneck'];
  var LS_BEST = 'arcade_best_' + GAME;
  var cta = document.getElementById('cta');
  var IS_LOCAL = /^(localhost|127\.0\.0\.1|::1|0\.0\.0\.0)$/.test(window.location.hostname);
  var PH_KEY = 'phc_tdju2w288PnkFE2e96efWKpoCvBPHPtveSztZK9NnGrv';
  if (!IS_LOCAL && PH_KEY.indexOf('__PH_') !== 0 && !window.posthog) {
    try {
      var phs = document.createElementNS('http://www.w3.org/2000/svg', 'script');
      phs.setAttribute('href', 'https://us-assets.i.posthog.com/static/array.js');
      phs.setAttribute('type', 'text/javascript');
      phs.onload = function () { try { window.posthog.init(PH_KEY, { defaults: '2026-05-30', persistence: 'localStorage+cookie', api_host: 'https://us.i.posthog.com', capture_pageview: true, capture_pageleave: true, autocapture: true, capture_exceptions: true, session_recording: { maskAllInputs: true } }); } catch (e) {} };
      document.documentElement.appendChild(phs);
    } catch (e) {}
  }
  function ph(name, props) { try { if (window.posthog && window.posthog.capture) window.posthog.capture(name, props || {}); } catch (e) {} }
  function lsGet(k, d) { try { var v = localStorage.getItem(k); return v === null ? d : v; } catch (e) { return d; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
  function bestOf() { return parseInt(lsGet(LS_BEST, '0'), 10) || 0; }
  function todayStr() { var n = new Date(); return n.getFullYear() + '-' + ('0' + (n.getMonth() + 1)).slice(-2) + '-' + ('0' + n.getDate()).slice(-2); }
  function todayGame() { return DAILY_GAMES[Math.floor(Date.now() / 86400000) % DAILY_GAMES.length]; }
  function markDaily() {
    var t = todayStr();
    var y = new Date(); y.setDate(y.getDate() - 1);
    var yst = y.getFullYear() + '-' + ('0' + (y.getMonth() + 1)).slice(-2) + '-' + ('0' + y.getDate()).slice(-2);
    var streak = lsGet('arcade_daily_date', '') === yst ? (parseInt(lsGet('arcade_streak', '0'), 10) || 0) + 1 : 1;
    lsSet('arcade_daily_date', t); lsSet('arcade_daily_done', '1'); lsSet('arcade_streak', String(streak));
    ph('daily_completed', { game: GAME, streak: streak });
  }
  function showCTA(on) { if (cta) cta.style.display = on ? 'block' : 'none'; }
  function wireCTA() {
    if (!cta) return;
    var links = cta.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      links[i].addEventListener('click', function () {
        var href = this.getAttribute('href') || '';
        var channel = href.indexOf('linkedin') !== -1 ? 'linkedin' : (href.indexOf('t.me') !== -1 ? 'telegram' : 'other');
        ph('contact_click', { location: 'game_over', channel: channel, game: GAME });
      });
    }
  }
  // —— /retention ——

  function spawn() { dots.push({x: 40 + Math.random() * 320, y: 92, s: 1.4 + Math.random() * 1.0, ret: Math.random() < 0.55, lbl: labels[Math.floor(Math.random() * 3)]}); }

  function draw() {
    while (dotsG.firstChild) dotsG.removeChild(dotsG.firstChild);
    for (var i = 0; i < dots.length; i++) {
      var d = dots[i];
      var c = document.createElementNS(svgns, 'circle');
      c.setAttribute('cx', d.x); c.setAttribute('cy', d.y); c.setAttribute('r', 9);
      c.setAttribute('fill', d.ret ? '#3FCF8E' : '#c9c2a8');
      dotsG.appendChild(c);
      var t = document.createElementNS(svgns, 'text');
      t.setAttribute('x', d.x); t.setAttribute('y', d.y + 3); t.setAttribute('text-anchor', 'middle');
      t.setAttribute('fill', '#0a0a12'); t.setAttribute('font-size', '7'); t.setAttribute('font-weight', 'bold');
      t.textContent = d.lbl; dotsG.appendChild(t);
    }
  }

  function step() {
    if (keys['ArrowLeft'] || keys['a'] || keys['A']) px -= 6;
    if (keys['ArrowRight'] || keys['d'] || keys['D']) px += 6;
    px = Math.max(50, Math.min(350, px));
    paddle.setAttribute('x', px - 50);
    var newBest = false;
    for (var i = dots.length - 1; i >= 0; i--) {
      var d = dots[i];
      d.y += d.s;
      if (d.y + 9 >= 372 && d.y - 9 <= 395 && Math.abs(d.x - px) < 56) {
        if (d.ret) kept++; else lost++;
        dots.splice(i, 1);
        if (kept > best) { var oldBest = best; best = kept; lsSet(LS_BEST, String(best)); newBest = true; ph('best_broken', { game: GAME, old_best: oldBest, new_best: best, score: kept }); }
      } else if (d.y > 395) { if (d.ret) lost++; dots.splice(i, 1); }
    }
    var total = kept + lost, ret = total ? Math.round(kept / total * 100) : 0;
    statusT.textContent = 'Retention ' + ret + '% · kept ' + kept + ' · lost ' + lost + ' · Best ' + Math.max(bestOf(), best);
    if (newBest || (kept >= DAILY_TARGET && !dailyFired)) {
      if (kept >= DAILY_TARGET && !dailyFired) { dailyFired = true; markDaily(); }
      showCTA(true);
      ph('milestone', { game: GAME, kept: kept, best: Math.max(bestOf(), best), daily_done: kept >= DAILY_TARGET });
    }
    draw();
  }

  document.addEventListener('keydown', function (e) { keys[e.key] = true; });
  document.addEventListener('keyup', function (e) { keys[e.key] = false; });
  document.addEventListener('mousemove', function (e) {
    var rect = document.documentElement.getBoundingClientRect();
    px = (e.clientX - rect.left) * (400 / rect.width);
    px = Math.max(50, Math.min(350, px));
  });

  // --- Touch controls (mobile) ---
  function touchPaddleX(clientX) {
    var rect = document.documentElement.getBoundingClientRect();
    px = (clientX - rect.left) * (400 / rect.width);
    px = Math.max(50, Math.min(350, px));
  }
  document.addEventListener('touchstart', function (e) { e.preventDefault(); touchPaddleX(e.touches[0].clientX); }, {passive: false});
  document.addEventListener('touchmove', function (e) { e.preventDefault(); touchPaddleX(e.touches[0].clientX); }, {passive: false});

  wireCTA();
  best = bestOf();
  ph('game_started', { game: GAME });
  for (var i = 0; i < 3; i++) spawn();
  setInterval(step, 16);
  function scheduleSpawn() {
    setTimeout(function () { spawn(); scheduleSpawn(); }, Math.max(400, 820 - kept * 3));
  }
  scheduleSpawn();
  draw();
})();
